"""Randomized differential test for the SCAMP-Trie pipeline."""
import json, os, random, subprocess, sys
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from ref import norm, lpm, build_image

BIN = None

def run_request(payload):
    r = subprocess.run([sys.executable, os.path.join(os.path.dirname(__file__), '..', 'run.py')],
                       input=json.dumps(payload).encode(), capture_output=True,
                       cwd=os.path.dirname(os.path.dirname(os.path.abspath(__file__))))
    if r.returncode != 0:
        raise RuntimeError('exit %d: %s' % (r.returncode, r.stderr[:400].decode()))
    return json.loads(r.stdout.decode('utf-8'))

def rand_addr(rng):
    return '%032x' % rng.getrandbits(128)

def make_case(rng, npfx, styles, nquery=6, nsnap=1, nload=1, external=True):
    """Build one case; returns (ops, expected_answers, expected_loads)."""
    ops = []
    live = {}
    snaps = []            # list of fib snapshots (dicts)
    answers = []
    loads = []
    front16 = set(); front64 = set()
    # ---- prefix pool
    pool = []
    for _ in range(npfx):
        style = rng.choice(styles)
        if style == 'v4ish':
            a = '00000000000000000000' + ('%08x' % rng.getrandbits(32))
            l = rng.randint(0, 32)
        elif style == 'v6':
            a = rand_addr(rng)
            l = rng.choice([0, 1, 15, 16, 17, 18, 32, 48, 63, 64, 65, 66, 80, 100, 112, 127, 128,
                            rng.randint(0, 128)])
        elif style == 'cluster':
            a = '20010db8' + ('%024x' % rng.getrandbits(96))
            l = rng.choice([16, 17, 32, 48, 64, 65, 96, 128])
        else:
            a = rand_addr(rng); l = rng.randint(0, 128)
        pool.append((a, l))
    rng.shuffle(pool)
    put_ops = []
    for (a, l) in pool:
        hop = rng.choice([0, 1, 7, 65536, 4194302, rng.randint(0, 4194302)])
        put_ops.append(["put", a, l, hop])
        p = norm(a, l)
        live[(p, l)] = hop
        if 16 < l <= 64: front16.add(p >> 112)
        elif l > 64: front64.add(p >> 64)
    # duplicate puts to exercise last-write-wins
    for _ in range(rng.randint(0, 4)):
        (a, l) = pool[rng.randrange(len(pool))]
        hop = rng.randint(0, 4194302)
        put_ops.append(["put", a, l, hop])
        live[(norm(a, l), l)] = hop
    # interleave puts and queries
    qi = 0
    idx = 0
    plan = []
    nq_total = nquery
    for i in range(len(put_ops)):
        plan.append(('P', put_ops[i]))
        if rng.random() < 0.15 and nq_total > 0:
            plan.append(('Q', None)); nq_total -= 1
    while nq_total > 0:
        plan.append(('Q', None)); nq_total -= 1
    cur_live = {}
    for kind, item in plan:
        if kind == 'P':
            ops.append(item)
            cur_live[(norm(item[1], item[2]), item[2])] = item[3]
        else:
            addrs = [rand_addr(rng) for _ in range(rng.randint(1, 3))]
            # include addresses that match prefixes
            for _ in range(rng.randint(0, 2)):
                if pool:
                    a = pool[rng.randrange(len(pool))][0]
                    addrs.append(a)
            ops.append(["query", addrs])
            for a in addrs:
                answers.append(lpm(cur_live, int(a, 16)))
    # ---- save / load
    saved_state = []
    for s in range(nsnap):
        ops.append(["save"])
        saved_state.append(dict(live))
        # after each save, load it and query the image
        if nload > 0:
            ops.append(["load_saved", s]); loads.append(True); nload -= 1
            addrs = [rand_addr(rng) for _ in range(2)]
            for _ in range(2):
                if pool: addrs.append(pool[rng.randrange(len(pool))][0])
            ops.append(["image_query", addrs])
            for a in addrs:
                answers.append(lpm(live, int(a, 16)))
        # mutate the live FIB afterwards to prove detachment
        if s == 0 and rng.random() < 0.7 and pool:
            a, l = pool[rng.randrange(len(pool))]
            hop = rng.randint(0, 4194302)
            ops.append(["put", a, l, hop])
            live[(norm(a, l), l)] = hop
            addrs = [a, rand_addr(rng)]
            ops.append(["query", addrs])
            for x in addrs: answers.append(lpm(live, int(x, 16)))
            ops.append(["image_query", addrs])
            for x in addrs: answers.append(lpm(saved_state[0], int(x, 16)))
    # ---- external images from the independent Python builder
    if external and saved_state:
        st = saved_state[0]
        variants = [
            dict(stage_policy='top', place_order='bulk-first', ni_order='stage-cell', direct_count=0),
            dict(stage_policy='height', place_order='full-first', ni_order='reverse', direct_count=0),
            dict(stage_policy='top', place_order='full-first', ni_order='bitmap', direct_count=3),
            dict(stage_policy='height', place_order='bulk-first', ni_order='stage-cell', direct_count=1,
                 type5_reverse=True),
        ]
        for v in variants:
            try:
                img = build_image(st, **v)
            except BaseException as e:
                continue
            ops.append(["load", img]); loads.append(True)
            addrs = [rand_addr(rng) for _ in range(2)]
            for _ in range(2):
                if pool: addrs.append(pool[rng.randrange(len(pool))][0])
            ops.append(["image_query", addrs])
            for a in addrs: answers.append(lpm(st, int(a, 16)))
    return ops, answers, loads

def main():
    seed = int(sys.argv[1]) if len(sys.argv) > 1 else 1
    iters = int(sys.argv[2]) if len(sys.argv) > 2 else 30
    rng = random.Random(seed)
    styles = ['v4ish', 'v6', 'cluster', 'rand']
    bad = 0
    for it in range(iters):
        npfx = rng.choice([1, 2, 3, 5, 12, 40, 120, 400])
        ncases = rng.choice([1, 2])
        cases = []
        exp_answers = []; exp_loads = []; nsnap = []
        for c in range(ncases):
            ops, answers, loads = make_case(rng, npfx, styles,
                                            nquery=rng.randint(1, 8),
                                            nsnap=rng.randint(1, 3),
                                            external=True)
            cases.append({"ops": ops})
            exp_answers.append(answers); exp_loads.append(loads)
            nsnap.append(sum(1 for o in ops if o[0] == 'save'))
        payload = {"cases": cases}
        resp = run_request(payload)
        if 'error' in resp:
            print('ITER %d: error' % it); bad += 1; continue
        for ci, res in enumerate(resp['results']):
            if res['answers'] != exp_answers[ci]:
                print('ITER %d case %d: answers differ' % (it, ci))
                for k, (a, b) in enumerate(zip(res['answers'], exp_answers[ci])):
                    if a != b: print('  first diff at %d: got %r want %r' % (k, a, b)); break
                bad += 1
                break
            if res['loads'] != exp_loads[ci]:
                print('ITER %d case %d: loads differ: got %r want %r' % (it, ci, res['loads'], exp_loads[ci]))
                bad += 1; break
            if len(res['snapshots']) != nsnap[ci]:
                print('ITER %d case %d: snapshot count' % (it, ci)); bad += 1; break
        print('iter %d ok' % it if not bad else 'iter %d BAD' % it)
    print('BAD:', bad)
    return 1 if bad else 0

sys.exit(main())
